1	/**
2	 * DockerRunAdapter — ExecutorPort adapter for the local-docker profile (T8).
3	 *
4	 * submit() registers the handle with the broker, then runs:
5	 *   docker run -d \
6	 *     --name exec-<handle> \
7	 *     --network agents-net \
8	 *     --entrypoint /platform/runner.js \
9	 *     --restart=no \
10	 *     -v /platform-bin:/platform:ro \
11	 *     -v /workspaces/<task>:/workspace:rw \
12	 *     -e BRIEFING_PATH ... -e CALLBACK_URL ... \
13	 *     --label platform.handle=<handle> \
14	 *     executor:current
15	 *
16	 * The container runs the runner wrapper as PID 1. When the wrapper exits
17	 * (after POSTing result to broker), the container exits naturally.
18	 * `--rm` is NOT used so docker logs / inspect remain available until ack().
19	 *
20	 * Wrapper-crash safety net:
21	 *   `docker wait <container_id>` is run in background. If the container
22	 *   exits without a corresponding broker callback arriving within crashGraceMs,
23	 *   the adapter synthesises a "failed" completion via the broker's callback URL.
24	 *
25	 * ack():
26	 *   Runs `docker rm <container_id>` to clean up the exited container, and
27	 *   unlinks the result file. Delegates to broker.ack() to commit consumption.
28	 *
29	 * Orphan sweep:
30	 *   A periodic sweep scans `docker ps -a -f label=platform.handle=<handle>`
31	 *   for exited containers whose handles are no longer in the supervision map
32	 *   (i.e. have already been acked or are unknown) and removes them.
33	 */
34	
35	import { randomUUID } from "node:crypto";
36	import { unlinkSync } from "node:fs";
37	import { execFile } from "node:child_process";
38	import { promisify } from "node:util";
39	import * as http from "node:http";
40	import * as https from "node:https";
41	import type {
42	  ExecutorPort,
43	  ExecutorPortInput,
44	  ExecutorHandle,
45	  ExecutorResult,
46	  CompletionBrokerPort,
47	} from "@workflow/runtime-abi";
48	
49	const execFileAsync = promisify(execFile);
50	
51	// ── Types ─────────────────────────────────────────────────────────────────────
52	
53	export interface DockerRunAdapterOpts {
54	  /**
55	   * Docker image to run as the executor.
56	   * Defaults to the standard executor image tag.
57	   */
58	  executorImage?: string;
59	
60	  /**
61	   * Path to the runner.js wrapper inside the container.
62	   * Defaults to /platform/runner.js (mounted via platformBinDir).
63	   */
64	  runnerEntrypoint?: string;
65	
66	  /**
67	   * Host path to the directory containing runner.js.
68	   * Mounted read-only into the container at /platform.
69	   * Defaults to /workflow/runtime/runner-wrapper (standard container path).
70	   */
71	  platformBinDir?: string;
72	
73	  /**
74	   * Host directory under which per-task workspace dirs live.
75	   * Each task gets a subdirectory at `<workspacesDir>/<taskId>`.
76	   * Mounted read-write into the container at /workspace.
77	   * If not set, workspace mounting is skipped (tests may skip this).
78	   */
79	  workspacesDir?: string;
80	
81	  /**
82	   * Docker bridge network the containers join so they can reach the broker
83	   * by service-name DNS (e.g. `broker:7000`).
84	   * Defaults to `agents-net`.
85	   */
86	  dockerNetwork?: string;
87	
88	  /**
89	   * Maximum wall-clock milliseconds before the watchdog kills the container.
90	   * Defaults to 2 hours.
91	   */
92	  timeoutMs?: number;
93	
94	  /**
95	   * Grace window (ms) after container exit before the safety-net synthetic
96	   * failure is posted to the broker. Allows a callback that was in-flight at
97	   * crash time to arrive before we synthesize a failure.
98	   * Default: 5 000 ms.
99	   */
100	  crashGraceMs?: number;
101	
102	  /**
103	   * How often the orphan sweep runs (ms). Pass 0 to disable.
104	   * Default: 60 000 ms.
105	   */
106	  orphanSweepIntervalMs?: number;
107	
108	  /**
109	   * CompletionBrokerPort instance. Required for the async callback flow.
110	   * If absent, broker.register is skipped (useful in isolated unit tests).
111	   */
112	  broker?: CompletionBrokerPort;
113	
114	  /**
115	   * Extra environment variables passed to the container.
116	   */
117	  extraEnv?: Record<string, string>;
118	
119	  /**
120	   * Override the docker binary path (useful in tests).
121	   * Default: "docker".
122	   */
123	  dockerBin?: string;
124	}
125	
126	interface SupervisionEntry {
127	  containerId: string;
128	  containerName: string;
129	  startedAt: string; // ISO 8601
130	  nonce: string;
131	  callbackUrl: string;
132	  resultPath: string;
133	  taskId: string;
134	  featureId: string;
135	}
136	
137	// ── Defaults ──────────────────────────────────────────────────────────────────
138	
139	const DEFAULT_EXECUTOR_IMAGE = "executor:current";
140	const DEFAULT_RUNNER_ENTRYPOINT = "/platform/runner.js";
141	const DEFAULT_PLATFORM_BIN_DIR = "/workflow/runtime/runner-wrapper";
142	const DEFAULT_DOCKER_NETWORK = "agents-net";
143	const DEFAULT_TIMEOUT_MS = 7_200_000;
144	const DEFAULT_CRASH_GRACE_MS = 5_000;
145	const DEFAULT_ORPHAN_SWEEP_MS = 60_000;
146	
147	// ── Helpers ───────────────────────────────────────────────────────────────────
148	
149	function emit(event: Record<string, unknown>): void {
150	  console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
151	}
152	
153	/** HTTP POST — resolves regardless of response status. Rejects on transport error. */
154	function _httpPost(url: string, body: string): Promise<void> {
155	  return new Promise((resolve, reject) => {
156	    let u: URL;
157	    try {
158	      u = new URL(url);
159	    } catch {
160	      reject(new Error(`_httpPost: invalid URL: ${url}`));
161	      return;
162	    }
163	    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
164	    const req = lib.request(
165	      {
166	        hostname: u.hostname,
167	        port: u.port || (u.protocol === "https:" ? 443 : 80),
168	        path: u.pathname + u.search,
169	        method: "POST",
170	        headers: {
171	          "Content-Type": "application/json",
172	          "Content-Length": Buffer.byteLength(body),
173	        },
174	      },
175	      (res) => {
176	        res.resume();
177	        resolve();
178	      },
179	    );
180	    req.on("error", reject);
181	    req.write(body);
182	    req.end();
183	  });
184	}
185	
186	// ── DockerRunAdapter ──────────────────────────────────────────────────────────
187	
188	export class DockerRunAdapter implements ExecutorPort {
189	  private readonly executorImage: string;
190	  private readonly runnerEntrypoint: string;
191	  private readonly platformBinDir: string;
192	  private readonly workspacesDir: string | undefined;
193	  private readonly dockerNetwork: string;
194	  private readonly timeoutMs: number;
195	  private readonly crashGraceMs: number;
196	  private readonly orphanSweepIntervalMs: number;
197	  private readonly broker: CompletionBrokerPort | null;
198	  private readonly extraEnv: Record<string, string>;
199	  private readonly dockerBin: string;
200	
201	  /** Keyed by handle; tracks in-flight containers for the safety-net sweep. */
202	  private readonly supervision = new Map<ExecutorHandle, SupervisionEntry>();
203	
204	  private orphanSweepTimer: ReturnType<typeof setInterval> | null = null;
205	
206	  constructor(opts: DockerRunAdapterOpts = {}) {
207	    this.executorImage = opts.executorImage ?? DEFAULT_EXECUTOR_IMAGE;
208	    this.runnerEntrypoint = opts.runnerEntrypoint ?? DEFAULT_RUNNER_ENTRYPOINT;
209	    this.platformBinDir = opts.platformBinDir ?? DEFAULT_PLATFORM_BIN_DIR;
210	    this.workspacesDir = opts.workspacesDir;
211	    this.dockerNetwork = opts.dockerNetwork ?? DEFAULT_DOCKER_NETWORK;
212	    this.timeoutMs = opts.timeoutMs ?? DEFAULT_TIMEOUT_MS;
213	    this.crashGraceMs = opts.crashGraceMs ?? DEFAULT_CRASH_GRACE_MS;
214	    this.orphanSweepIntervalMs = opts.orphanSweepIntervalMs ?? DEFAULT_ORPHAN_SWEEP_MS;
215	    this.broker = opts.broker ?? null;
216	    this.extraEnv = opts.extraEnv ?? {};
217	    this.dockerBin = opts.dockerBin ?? "docker";
218	
219	    if (this.orphanSweepIntervalMs > 0) {
220	      this.orphanSweepTimer = setInterval(() => {
221	        this._orphanSweep().catch((err) => {
222	          emit({ type: "orphan_sweep_error", error: String(err) });
223	        });
224	      }, this.orphanSweepIntervalMs);
225	      if (this.orphanSweepTimer.unref) this.orphanSweepTimer.unref();
226	    }
227	  }
228	
229	  // ── ExecutorPort ──────────────────────────────────────────────────────────
230	
231	  async submit(input: ExecutorPortInput): Promise<ExecutorHandle> {
232	    const {
233	      taskId,
234	      featureId,
235	      workspaceId,
236	      taskRepoUrl,
237	      taskRepoBranch,
238	      taskRepoPath,
239	      briefingPath,
240	      resultPath,
241	      budgetTokens,
242	      sshPrivateKey,
243	      githubToken,
244	      callbackUrl,
245	      nonce,
246	    } = input;
247	
248	    const handle = randomUUID();
249	    const startedAt = new Date().toISOString();
250	    const containerName = `exec-${handle}`;
251	
252	    // 1. Register handle with broker before spawning so callback arriving
253	    //    before submit returns is still accepted.
254	    if (this.broker) {
255	      await this.broker.register(handle, nonce, {
256	        kind: "impl",
257	        task_id: taskId,
258	        feature_id: featureId,
259	        started_at: startedAt,
260	      });
261	    }
262	
263	    // 2. Build docker run arguments.
264	    const envArgs: string[] = [
265	      "-e", `TASK_ID=${taskId}`,
266	      "-e", `FEATURE_ID=${featureId}`,
267	      "-e", `WORKSPACE_ID=${workspaceId}`,
268	      "-e", `TASK_REPO_URL=${taskRepoUrl}`,
269	      "-e", `TASK_REPO_BRANCH=${taskRepoBranch}`,
270	      "-e", `TASK_REPO_PATH=${taskRepoPath}`,
271	      "-e", `BRIEFING_PATH=${briefingPath}`,
272	      "-e", `RESULT_PATH=${resultPath}`,
273	      "-e", `GITHUB_TOKEN=${githubToken}`,
274	      "-e", `CALLBACK_URL=${callbackUrl}`,
275	      "-e", `HANDLE=${handle}`,
276	      "-e", `NONCE=${nonce}`,
277	    ];
278	
279	    if (sshPrivateKey) {
280	      envArgs.push("-e", `SSH_PRIVATE_KEY=${sshPrivateKey}`);
281	    }
282	    if (budgetTokens !== undefined) {
283	      envArgs.push("-e", `BUDGET_TOKENS=${budgetTokens}`);
284	    }
285	
286	    for (const [k, v] of Object.entries(this.extraEnv)) {
287	      envArgs.push("-e", `${k}=${v}`);
288	    }
289	
290	    const volumeArgs: string[] = [
291	      "-v", `${this.platformBinDir}:/platform:ro`,
292	    ];
293	    if (this.workspacesDir) {
294	      volumeArgs.push("-v", `${this.workspacesDir}:/workspace:rw`);
295	    }
296	
297	    const dockerArgs = [
298	      "run", "-d",
299	      "--name", containerName,
300	      "--network", this.dockerNetwork,
301	      "--entrypoint", this.runnerEntrypoint,
302	      "--restart=no",
303	      "--label", `platform.handle=${handle}`,
304	      ...envArgs,
305	      ...volumeArgs,
306	      this.executorImage,
307	    ];
308	
309	    emit({
310	      type: "executor_spawn",
311	      task_id: taskId,
312	      feature_id: featureId,
313	      handle,
314	      container_name: containerName,
315	      image: this.executorImage,
316	    });
317	
318	    // 3. docker run -d — returns container ID immediately.
319	    let containerId: string;
320	    try {
321	      const { stdout } = await execFileAsync(this.dockerBin, dockerArgs);
322	      containerId = stdout.trim();
323	    } catch (err) {
324	      // If docker run fails, unregister the handle and rethrow.
325	      if (this.broker) {
326	        await this.broker.ack(handle).catch(() => {/* best-effort */});
327	      }
328	      throw err;
329	    }
330	
331	    // 4. Track in supervision map.
332	    this.supervision.set(handle, {
333	      containerId,
334	      containerName,
335	      startedAt,
336	      nonce,
337	      callbackUrl,
338	      resultPath,
339	      taskId,
340	      featureId,
341	    });
342	
343	    // 5. docker wait as the wrapper-crash safety net (runs async).
344	    this._watchContainer(handle, containerId, containerName, callbackUrl, nonce, taskId, featureId);
345	
346	    return handle;
347	  }
348	
349	  /**
350	   * readResult is a no-op for local-docker — result rides in the callback.
351	   * Returns a tombstone so callers that mistakenly call readResult get a
352	   * predictable signal.
353	   */
354	  async readResult(_handle: ExecutorHandle): Promise<ExecutorResult> {
355	    return { terminal_status: "failed", blocked_reason: "handle_not_found" };
356	  }
357	
358	  // ── ack ───────────────────────────────────────────────────────────────────
359	
360	  /**
361	   * Acknowledge a completed handle:
362	   *  - Removes the entry from the supervision map (disarms the safety net).
363	   *  - Runs `docker rm <container_id>` to clean up the exited container.
364	   *  - Unlinks the result file.
365	   *  - Delegates to broker.ack.
366	   */
367	  async ack(handle: ExecutorHandle): Promise<void> {
368	    const entry = this.supervision.get(handle);
369	    if (entry) {
370	      this.supervision.delete(handle);
371	
372	      // docker rm — best-effort; container may already be removed.
373	      try {
374	        await execFileAsync(this.dockerBin, ["rm", entry.containerId]);
375	      } catch {
376	        // Container may already be gone (manual cleanup, restart, etc.).
377	      }
378	
379	      // Unlink result file — best-effort.
380	      try {
381	        unlinkSync(entry.resultPath);
382	      } catch {
383	        // File may already be gone.
384	      }
385	    }
386	
387	    if (this.broker) {
388	      await this.broker.ack(handle);
389	    }
390	  }
391	
392	  // ── Supervision helpers ───────────────────────────────────────────────────
393	
394	  /** Number of handles currently tracked in the supervision map. */
395	  supervisionSize(): number {
396	    return this.supervision.size;
397	  }
398	
399	  /** Stop the orphan sweep timer. Call during graceful shutdown. */
400	  stopOrphanSweep(): void {
401	    if (this.orphanSweepTimer) {
402	      clearInterval(this.orphanSweepTimer);
403	      this.orphanSweepTimer = null;
404	    }
405	  }
406	
407	  // ── Internal ─────────────────────────────────────────────────────────────
408	
409	  /**
410	   * Run `docker wait <containerId>` in the background. When the container
411	   * exits, if the handle is still in the supervision map (no callback arrived
412	   * yet), fire a synthetic "failed" completion to the broker after crashGraceMs.
413	   */
414	  private _watchContainer(
415	    handle: ExecutorHandle,
416	    containerId: string,
417	    containerName: string,
418	    callbackUrl: string,
419	    nonce: string,
420	    taskId: string,
421	    featureId: string,
422	  ): void {
423	    // Watchdog: kill the container if it exceeds the wall-clock timeout.
424	    let watchdog: ReturnType<typeof setTimeout> | null = setTimeout(() => {
425	      watchdog = null;
426	      emit({
427	        type: "executor_timeout",
428	        task_id: taskId,
429	        feature_id: featureId,
430	        handle,
431	        container_id: containerId,
432	        timeout_ms: this.timeoutMs,
433	      });
434	      execFileAsync(this.dockerBin, ["stop", containerName]).catch(() => {/* best-effort */});
435	    }, this.timeoutMs);
436	    if (watchdog.unref) watchdog.unref();
437	
438	    // docker wait — blocks until container exits; run async.
439	    execFileAsync(this.dockerBin, ["wait", containerId])
440	      .then(({ stdout }) => {
441	        const exitCode = parseInt(stdout.trim(), 10);
442	
443	        if (watchdog !== null) {
444	          clearTimeout(watchdog);
445	          watchdog = null;
446	        }
447	
448	        emit({
449	          type: "executor_exit",
450	          task_id: taskId,
451	          feature_id: featureId,
452	          handle,
453	          container_id: containerId,
454	          exit_code: exitCode,
455	        });
456	
457	        // Grace timer before firing safety net.
458	        const graceTimer = setTimeout(() => {
459	          if (!this.supervision.has(handle)) return; // already acked
460	          const entry = this.supervision.get(handle)!;
461	          this.supervision.delete(handle);
462	
463	          const reason =
464	            exitCode !== 0
465	              ? `runner_crashed (exit ${exitCode})`
466	              : "runner_no_callback";
467	
468	          emit({
469	            type: "executor_safety_net",
470	            task_id: entry.taskId,
471	            feature_id: entry.featureId,
472	            handle,
473	            container_id: containerId,
474	            reason,
475	          });
476	
477	          const body = JSON.stringify({
478	            handle,
479	            nonce: entry.nonce,
480	            result: { terminal_status: "failed", blocked_reason: reason },
481	          });
482	
483	          _httpPost(entry.callbackUrl, body).catch(() => {
484	            // Best-effort — ignore POST failures in the safety net.
485	          });
486	        }, this.crashGraceMs);
487	
488	        if (graceTimer.unref) graceTimer.unref();
489	      })
490	      .catch(() => {
491	        // docker wait failed (container removed before we could wait, etc.).
492	        // The safety net won't fire, but the broker's visibility timeout will
493	        // reclaim the completion eventually.
494	        if (watchdog !== null) {
495	          clearTimeout(watchdog);
496	          watchdog = null;
497	        }
498	      });
499	  }
500	
501	  /**
502	   * Periodic orphan sweep.
503	   *
504	   * Lists all containers with a `platform.handle` label, checks which ones
505	   * are exited and whose handles are NOT in the in-flight supervision map
506	   * (i.e. already acked or never registered), and removes them.
507	   */
508	  private async _orphanSweep(): Promise<void> {
509	    let stdout: string;
510	    try {
511	      const result = await execFileAsync(this.dockerBin, [
512	        "ps", "-a",
513	        "--filter", "label=platform.handle",
514	        "--format", "{{.ID}}\t{{.Label \"platform.handle\"}}\t{{.Status}}",
515	      ]);
516	      stdout = result.stdout;
517	    } catch {
518	      return; // docker unavailable; skip sweep
519	    }
520	
521	    const lines = stdout.trim().split("\n").filter(Boolean);
522	    for (const line of lines) {
523	      const [containerId, handle, status] = line.split("\t");
524	      if (!containerId || !handle || !status) continue;
525	
526	      // Only remove exited containers whose handles are not in supervision.
527	      if (status.toLowerCase().startsWith("exited") && !this.supervision.has(handle)) {
528	        emit({
529	          type: "orphan_container_removed",
530	          container_id: containerId,
531	          handle,
532	        });
533	        execFileAsync(this.dockerBin, ["rm", containerId]).catch(() => {/* best-effort */});
534	      }
535	    }
536	  }
537	}
538

