1	/**
2	 * Integration tests for DockerRunAdapter (T8).
3	 *
4	 * Docker is not required — a fake docker binary simulates container lifecycle
5	 * via a state file and real Node child processes. The runner entrypoint path
6	 * is set to the host path of the fake runner script so the fake docker binary
7	 * can invoke it directly.
8	 *
9	 * Scenarios covered:
10	 *   1. Happy path — fake container POSTs a valid result; broker delivers it.
11	 *   2. Wrapper crash before POST — container exits non-zero; safety net fires
12	 *      a synthetic "failed" completion.
13	 *   3. Broker-reject (replay) — container POSTs twice; second POST after ack
14	 *      returns 401; only one completion delivered.
15	 *   4. ack() removes supervision entry, removes container, unlinks result file.
16	 *   5. submit() returns a non-empty handle immediately (non-blocking).
17	 *   6. Orphan sweep removes exited containers not in supervision.
18	 */
19	
20	import { describe, it, expect, beforeEach, afterEach } from "vitest";
21	import {
22	  mkdtempSync,
23	  rmSync,
24	  writeFileSync,
25	  existsSync,
26	  readFileSync,
27	} from "node:fs";
28	import { join } from "node:path";
29	import { tmpdir } from "node:os";
30	
31	import { InMemoryBrokerAdapter } from "../src/adapters/broker/in-memory.js";
32	import { DockerRunAdapter } from "../src/adapters/executor/docker-run.js";
33	
34	// ── Helpers ───────────────────────────────────────────────────────────────────
35	
36	const tmpDirs: string[] = [];
37	
38	function makeTmpDir(prefix: string): string {
39	  const dir = mkdtempSync(join(tmpdir(), prefix));
40	  tmpDirs.push(dir);
41	  return dir;
42	}
43	
44	async function waitForCompletion(
45	  broker: InMemoryBrokerAdapter,
46	  timeoutMs = 15_000,
47	  pollMs = 50,
48	): Promise<ReturnType<typeof broker.listCompleted> extends Promise<(infer T)[]> ? T : never> {
49	  const deadline = Date.now() + timeoutMs;
50	  while (Date.now() < deadline) {
51	    const items = await broker.listCompleted({ max: 1, lockMs: 30_000 });
52	    if (items.length > 0) return items[0] as any;
53	    await new Promise((r) => setTimeout(r, pollMs));
54	  }
55	  throw new Error(`waitForCompletion: no completion arrived within ${timeoutMs}ms`);
56	}
57	
58	function makeInput(overrides: {
59	  briefingPath?: string;
60	  resultPath: string;
61	  callbackUrl: string;
62	  nonce: string;
63	  taskId?: string;
64	  featureId?: string;
65	}) {
66	  return {
67	    taskId: overrides.taskId ?? "T8",
68	    featureId: overrides.featureId ?? "runtime-portable-architecture",
69	    workspaceId: "test-ws",
70	    taskRepoUrl: "git@github.com:org/repo.git",
71	    taskRepoBranch: "feature/runtime-portable-architecture-T8",
72	    taskRepoPath: "/tmp/task-repo",
73	    briefingPath: overrides.briefingPath ?? "/tmp/briefing.md",
74	    resultPath: overrides.resultPath,
75	    sshPrivateKey: "",
76	    githubToken: "",
77	    callbackUrl: overrides.callbackUrl,
78	    nonce: overrides.nonce,
79	  };
80	}
81	
82	/**
83	 * Write a fake docker binary to `binDir/docker`.
84	 *
85	 * The fake binary supports:
86	 *  - `docker run -d --entrypoint <runner> ...` — spawns the runner script as
87	 *     a real Node child with env vars extracted from `-e KEY=VALUE` args.
88	 *     Writes state to stateFile. Returns a fake container ID.
89	 *  - `docker wait <id>` — polls until the process exits; returns exit code.
90	 *  - `docker rm <id>` — removes container from state.
91	 *  - `docker stop <id>` — SIGTERMs the process.
92	 *  - `docker ps -a --filter label=... --format ...` — lists state entries.
93	 *
94	 * State: JSON file at stateFile mapping containerId → { pid, exitCode, labels }.
95	 */
96	function writeFakeDocker(binDir: string, stateFile: string): string {
97	  const dockerBin = join(binDir, "docker");
98	  const script = /* javascript */ `#!/usr/bin/env node
99	'use strict';
100	const cp = require('node:child_process');
101	const fs = require('node:fs');
102	const crypto = require('node:crypto');
103	
104	const STATE_FILE = ${JSON.stringify(stateFile)};
105	
106	function loadState() {
107	  try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8')); } catch { return {}; }
108	}
109	function saveState(s) {
110	  fs.writeFileSync(STATE_FILE, JSON.stringify(s, null, 2));
111	}
112	
113	const args = process.argv.slice(2);
114	const cmd = args[0];
115	
116	// ── docker run -d ──────────────────────────────────────────────────────────
117	if (cmd === 'run' && args.includes('-d')) {
118	  // Extract --entrypoint (the runner script host path in tests).
119	  let entrypoint = null;
120	  const envVars = {};
121	  const labels = {};
122	  for (let i = 0; i < args.length; i++) {
123	    if (args[i] === '--entrypoint' && args[i+1]) { entrypoint = args[i+1]; i++; continue; }
124	    if (args[i] === '-e' && args[i+1]) {
125	      const eqIdx = args[i+1].indexOf('=');
126	      if (eqIdx !== -1) {
127	        envVars[args[i+1].slice(0, eqIdx)] = args[i+1].slice(eqIdx + 1);
128	      }
129	      i++;
130	      continue;
131	    }
132	    if (args[i] === '--label' && args[i+1]) {
133	      const eqIdx = args[i+1].indexOf('=');
134	      if (eqIdx !== -1) {
135	        labels[args[i+1].slice(0, eqIdx)] = args[i+1].slice(eqIdx + 1);
136	      }
137	      i++;
138	      continue;
139	    }
140	  }
141	  if (!entrypoint) {
142	    process.stderr.write('fake-docker run: no --entrypoint provided\\n');
143	    process.exit(1);
144	  }
145	  const containerId = crypto.randomBytes(12).toString('hex');
146	  const child = cp.spawn('node', [entrypoint], {
147	    env: { ...process.env, ...envVars },
148	    stdio: 'ignore',
149	    detached: true,
150	  });
151	  child.unref();
152	  const state = loadState();
153	  state[containerId] = { pid: child.pid, exitCode: null, labels };
154	  saveState(state);
155	  process.stdout.write(containerId + '\\n');
156	  process.exit(0);
157	}
158	
159	// ── docker wait <id> ───────────────────────────────────────────────────────
160	if (cmd === 'wait') {
161	  const cid = args[1];
162	  const maxWait = 30_000;
163	  const start = Date.now();
164	  const poll = () => {
165	    const state = loadState();
166	    if (!state[cid]) { process.stdout.write('0\\n'); process.exit(0); }
167	    const { pid } = state[cid];
168	    let running = true;
169	    try { process.kill(pid, 0); } catch { running = false; }
170	    if (!running) {
171	      process.stdout.write(String(state[cid].exitCode ?? 0) + '\\n');
172	      process.exit(0);
173	    }
174	    if (Date.now() - start > maxWait) { process.stdout.write('1\\n'); process.exit(0); }
175	    setTimeout(poll, 100);
176	  };
177	  setTimeout(poll, 50);
178	  return;
179	}
180	
181	// ── docker rm <id> ─────────────────────────────────────────────────────────
182	if (cmd === 'rm') {
183	  const cid = args[1];
184	  const state = loadState();
185	  delete state[cid];
186	  saveState(state);
187	  process.exit(0);
188	}
189	
190	// ── docker stop <id> ──────────────────────────────────────────────────────
191	if (cmd === 'stop') {
192	  const cid = args[1];
193	  const state = loadState();
194	  if (state[cid]) { try { process.kill(state[cid].pid, 'SIGTERM'); } catch {} }
195	  process.exit(0);
196	}
197	
198	// ── docker ps -a --filter label=platform.handle --format ... ─────────────
199	if (cmd === 'ps') {
200	  const state = loadState();
201	  const lines = [];
202	  for (const [cid, entry] of Object.entries(state)) {
203	    const { pid, labels, exitCode } = entry;
204	    let running = true;
205	    try { process.kill(pid, 0); } catch { running = false; }
206	    const status = running ? 'Up 1 second' : \`Exited (\${exitCode ?? 0}) 1 second ago\`;
207	    const handle = (labels || {})['platform.handle'] || '';
208	    if (handle) lines.push(cid + '\\t' + handle + '\\t' + status);
209	  }
210	  process.stdout.write(lines.join('\\n') + (lines.length ? '\\n' : ''));
211	  process.exit(0);
212	}
213	
214	process.stderr.write('fake-docker: unknown: ' + args.join(' ') + '\\n');
215	process.exit(1);
216	`;
217	  writeFileSync(dockerBin, script, { mode: 0o755 });
218	  return dockerBin;
219	}
220	
221	// ── Suite setup ───────────────────────────────────────────────────────────────
222	
223	let broker: InMemoryBrokerAdapter;
224	let callbackUrl: string;
225	
226	beforeEach(async () => {
227	  broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
228	  await broker.start();
229	  callbackUrl = broker.getCallbackUrl()!;
230	});
231	
232	afterEach(async () => {
233	  await broker.stop();
234	  while (tmpDirs.length) {
235	    const d = tmpDirs.pop()!;
236	    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
237	  }
238	});
239	
240	// ── 1. Happy path ─────────────────────────────────────────────────────────────
241	
242	describe("DockerRunAdapter — happy path", () => {
243	  it("submit() returns handle; broker delivers result via callback", async () => {
244	    const dir = makeTmpDir("dr-happy-");
245	    const stateFile = join(dir, "state.json");
246	    const resultPath = join(dir, "result.json");
247	    const nonce = "nonce-docker-happy-001";
248	
249	    const runnerPath = join(dir, "runner.cjs");
250	    writeFileSync(
251	      runnerPath,
252	      [
253	        `const http = require("node:http");`,
254	        `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
