main.go
// Command broker runs the Redis-backed completion broker service.
//
// Environment variables:
//
//	BROKER_ADDR      Listen address (default ":7000")
//	REDIS_URL        Redis connection URL (default "redis://localhost:6379")
//	RECLAIM_INTERVAL Reclaim sweep cadence in seconds (default "2")
package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"github.com/redis/go-redis/v9"
	"github.com/tiendv89/agent-workflow/runtime/broker/internal/server"
	"github.com/tiendv89/agent-workflow/runtime/broker/internal/store"
)

func main() {
	addr := envOrDefault("BROKER_ADDR", ":7000")
	redisURL := envOrDefault("REDIS_URL", "redis://localhost:6379")
	reclaimSecs := envIntOrDefault("RECLAIM_INTERVAL", 2)

	// Connect to Redis.
	opts, err := redis.ParseURL(redisURL)
	if err != nil {
		log.Fatalf("invalid REDIS_URL %q: %v", redisURL, err)
	}
	rdb := redis.NewClient(opts)

	ctx := context.Background()
	if err := rdb.Ping(ctx).Err(); err != nil {
		log.Fatalf("redis ping failed: %v", err)
	}
	log.Printf("connected to Redis at %s", redisURL)

	st := store.NewRedisStore(rdb)
	srv := server.New(st)

	// Reclaim sweep runs in the background.
	reclaimInterval := time.Duration(reclaimSecs) * time.Second
	go runReclaimLoop(ctx, st, reclaimInterval)

	httpServer := &http.Server{
		Addr:    addr,
		Handler: srv,
	}

	// Graceful shutdown on SIGTERM / SIGINT.
	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGTERM, syscall.SIGINT)

	go func() {
		log.Printf("broker listening on %s", addr)
		if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen error: %v", err)
		}
	}()

	<-quit
	log.Println("shutting down broker…")

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := httpServer.Shutdown(shutdownCtx); err != nil {
		log.Printf("shutdown error: %v", err)
	}
	if err := rdb.Close(); err != nil {
		log.Printf("redis close error: %v", err)
	}
	log.Println("broker stopped")
}

func runReclaimLoop(ctx context.Context, st store.Store, interval time.Duration) {
	ticker := time.NewTicker(interval)
	defer ticker.Stop()
	for {
		select {
		case <-ticker.C:
			if err := st.ReclaimExpired(ctx); err != nil {
				log.Printf("reclaim error: %v", err)
			}
		case <-ctx.Done():
			return
		}
	}
}

func envOrDefault(key, def string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return def
}

func envIntOrDefault(key string, def int) int {
	v := os.Getenv(key)
	if v == "" {
		return def
	}
	n, err := strconv.Atoi(v)
	if err != nil {
		fmt.Fprintf(os.Stderr, "warning: invalid %s=%q; using default %d\n", key, v, def)
		return def
	}
	return n
}

