/**
 * local-docker profile factory.
 *
 * Bundles the Wave-4 adapter set into a RuntimePorts instance for the
 * M:N multi-container topology: each orchestrator spawns per-task executor
 * containers via `docker run -d`; all completions route through a shared
 * Redis-backed broker service.
 *
 * Adapter set:
 *   ExecutorPort         → DockerRunAdapter     (docker run -d, --network agents-net)
 *   CompletionBrokerPort → HttpBrokerAdapter    (calls Go broker service at BROKER_URL)
 *   BriefingTransport    → LocalFileBriefingAdapter
 *   WorkflowState        → GitWorkflowStateAdapter
 *   Credential           → EnvCredentialAdapter
 *   WorkspacePull        → GitClonePullAdapter
 *   EventEmitter         → StdoutJsonEmitter
 *   Scheduler            → SimpleSleepScheduler
 *   Clock                → RealClock
 *
 * Topology:
 *   - All orchestrator containers, executor containers, the broker container,
 *     and the Redis container share the `agents-net` bridge network.
 *   - Orchestrators have the Docker socket mounted so they can `docker run`
 *     executor containers attached to the same bridge.
 *   - Runners reach the broker at http://broker:7000/callback via service-name DNS.
 *   - Any orchestrator drains any completion (opportunistic dispatch).
 */

import type { RuntimePorts } from "../runtime-ports.js";
import { DockerRunAdapter, type DockerRunAdapterOpts } from "../adapters/executor/docker-run.js";
import { HttpBrokerAdapter, type HttpBrokerAdapterOpts } from "../adapters/broker/http.js";
import { LocalFileBriefingAdapter } from "../adapters/briefing/local-file.js";
import { GitWorkflowStateAdapter } from "../adapters/workflow-state/git.js";
import { EnvCredentialAdapter } from "../adapters/credential/env.js";
import { GitClonePullAdapter } from "../adapters/workspace-pull/git-clone-pull.js";
import { StdoutJsonEmitter } from "../adapters/emitter/stdout-json.js";
import { SimpleSleepScheduler } from "../adapters/scheduler/simple-sleep.js";
import { RealClock } from "../adapters/clock/real.js";

export interface LocalDockerProfileOpts {
  /** Options forwarded to DockerRunAdapter. */
  executor?: DockerRunAdapterOpts;
  /** Options forwarded to HttpBrokerAdapter. */
  broker?: HttpBrokerAdapterOpts;
  /** Base URL of the Go broker service. Defaults to http://broker:7000. */
  brokerUrl?: string;
  /** Git identity for WorkflowStatePort operations. */
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
}

/** The broker is part of the profile bundle so callers can call getCallbackUrl(). */
export interface LocalDockerProfileBundle extends RuntimePorts {
  broker: HttpBrokerAdapter;
  executor: DockerRunAdapter;
}

/**
 * Create a RuntimePorts bundle wired for the local-docker profile.
 *
 * The broker's getCallbackUrl() returns the Go broker service callback
 * URL (e.g. http://broker:7000/callback). Pass this to ExecutorPortInput
 * as callbackUrl when submitting tasks.
 *
 * Example:
 *   const bundle = createLocalDockerProfile({ gitAuthorEmail: '...', brokerUrl: 'http://broker:7000' });
 *   const callbackUrl = bundle.broker.getCallbackUrl();
 *   // pass bundle to orchestrator concerns...
 *   bundle.executor.stopOrphanSweep(); // on graceful shutdown
 */
export function createLocalDockerProfile(
  opts: LocalDockerProfileOpts,
): LocalDockerProfileBundle {
  const brokerUrl = opts.brokerUrl ?? opts.broker?.brokerUrl ?? "http://broker:7000";
  const broker = new HttpBrokerAdapter(
    opts.broker ?? { brokerUrl },
  );
  const executor = new DockerRunAdapter({ ...opts.executor, broker });
  return {
    executor,
    broker,
    briefing: new LocalFileBriefingAdapter(),
    workflowState: new GitWorkflowStateAdapter({
      gitAuthorEmail: opts.gitAuthorEmail,
      gitAuthorName: opts.gitAuthorName,
      sshKeyPath: opts.sshKeyPath,
    }),
    credential: new EnvCredentialAdapter(),
    workspacePull: new GitClonePullAdapter(),
    emitter: new StdoutJsonEmitter(),
    scheduler: new SimpleSleepScheduler(),
    clock: new RealClock(),
  };
}

