private _handleRequest(req: http.IncomingMessage, res: http.ServerResponse): void {
  if (req.method !== "POST" || req.url !== "/callback") {
    res.writeHead(404);
    res.end(JSON.stringify({ error: "not_found" }));
    return;
  }

  const chunks: Buffer[] = [];
  req.on("data", (chunk: Buffer) => chunks.push(chunk));
  req.on("end", () => {
    let payload: RunnerCallbackPayload;
    try {
      payload = JSON.parse(Buffer.concat(chunks).toString("utf8"));
    } catch {
      res.writeHead(400, { "Content-Type": "application/json" });
      res.end(JSON.stringify({ error: "invalid_json" }));
      return;
    }

    const outcome = this._processCallback(payload);
    res.writeHead(outcome.status, { "Content-Type": "application/json" });
    res.end(JSON.stringify(outcome.body));
  });
}

private _processCallback(
  payload: RunnerCallbackPayload,
): { status: number; body: unknown } {
  const { handle, nonce, result } = payload;

  const entry = this.registry.get(handle);
  if (!entry) {
    return { status: 401, body: { error: "unknown_handle" } };
  }

  const expectedBuf = Buffer.from(entry.nonce);
  const actualBuf = Buffer.from(nonce);
  const nonceValid =
    expectedBuf.length === actualBuf.length &&
    crypto.timingSafeEqual(expectedBuf, actualBuf);
  if (!nonceValid) {
    return { status: 401, body: { error: "nonce_mismatch" } };
  }

  this.queue.push({
    handle,
    result,
    metadata: entry.metadata,
  });

  // Consume the nonce: remove registry entry so replay POSTs return 401.
  this.registry.delete(handle);

  return { status: 204, body: {} };
}

private _reclaimExpired(now: number): void {
  for (const item of this.queue) {
    if (item.locked_until !== undefined && item.locked_until <= now) {
      item.locked_until = undefined;

