/**
 * M:N topology test (T9) — multiple orchestrators sharing a single broker.
 *
 * Verifies the core property of the local-docker profile:
 *   "Submit and reap are decoupled — any orchestrator can drain any completion."
 *
 * Scenarios:
 *   1. 3 orchestrators (DockerRunAdapter instances) share 1 InMemoryBrokerAdapter.
 *   2. 5 tasks are submitted across the 3 orchestrators (non-uniform distribution).
 *   3. All 5 runners POST completions to the shared broker.
 *   4. 3 reap drainers independently poll listCompleted in a round-robin loop.
 *   5. All 5 completions are drained exactly once.
 *   6. At least one completion is drained by an orchestrator that did not submit it
 *      (opportunistic dispatch).
 *
 * Docker is not required — a fake docker binary simulates container lifecycle
 * via a state file, as in docker-run-adapter.test.ts.
 */

import { describe, it, expect, beforeEach, afterEach } from "vitest";
import {
  mkdtempSync,
  rmSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { randomUUID } from "node:crypto";

import { InMemoryBrokerAdapter } from "../src/adapters/broker/in-memory.js";
import { DockerRunAdapter } from "../src/adapters/executor/docker-run.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeTmpDir(prefix: string): string {
  const dir = mkdtempSync(join(tmpdir(), prefix));
  tmpDirs.push(dir);
  return dir;
}

function makeInput(overrides: {
  resultPath: string;
  callbackUrl: string;
  nonce: string;
  taskId: string;
}) {
  return {
    taskId: overrides.taskId,
    featureId: "runtime-portable-architecture",
    workspaceId: "test-ws",
    taskRepoUrl: "git@github.com:org/repo.git",
    taskRepoBranch: `feature/runtime-portable-architecture-${overrides.taskId}`,
    taskRepoPath: "/tmp/task-repo",
    briefingPath: "/tmp/briefing.md",
    resultPath: overrides.resultPath,
    sshPrivateKey: "",
    githubToken: "",
    callbackUrl: overrides.callbackUrl,
    nonce: overrides.nonce,
  };
}

/**
 * Write a fake docker binary.
 *
 * Supports the minimum set of commands used by DockerRunAdapter:
 *   docker run -d --entrypoint <runner> -e K=V ... → spawns runner as real Node child
 *   docker wait <id>   → polls until the process exits
 *   docker rm   <id>   → removes from state
 *   docker stop <id>   → SIGTERMs the process
 *   docker ps -a ...   → lists state (for orphan sweep)
 */
function writeFakeDocker(binDir: string, stateFile: string): string {
  const dockerBin = join(binDir, "docker");
  const script = /* javascript */ `#!/usr/bin/env node
'use strict';
const cp = require('node:child_process');
const fs = require('node:fs');
const crypto = require('node:crypto');

const STATE_FILE = ${JSON.stringify(stateFile)};

function loadState() {
  try { return JSON.parse(fs.readFileSync(STATE_FILE, 'utf-8')); } catch { return {}; }
}
function saveState(s) {
  fs.writeFileSync(STATE_FILE, JSON.stringify(s, null, 2));
}

const args = process.argv.slice(2);
const cmd = args[0];

if (cmd === 'run' && args.includes('-d')) {
  let entrypoint = null;
  const envVars = {};
  const labels = {};
  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--entrypoint' && args[i+1]) { entrypoint = args[i+1]; i++; continue; }
    if (args[i] === '-e' && args[i+1]) {
      const eqIdx = args[i+1].indexOf('=');
      if (eqIdx !== -1) envVars[args[i+1].slice(0, eqIdx)] = args[i+1].slice(eqIdx + 1);
      i++; continue;
    }
    if (args[i] === '--label' && args[i+1]) {
      const eqIdx = args[i+1].indexOf('=');
      if (eqIdx !== -1) labels[args[i+1].slice(0, eqIdx)] = args[i+1].slice(eqIdx + 1);
      i++; continue;
    }
  }
  if (!entrypoint) { process.stderr.write('fake-docker run: no --entrypoint\\n'); process.exit(1); }
  const containerId = crypto.randomBytes(12).toString('hex');
  const child = cp.spawn('node', [entrypoint], {
    env: { ...process.env, ...envVars },
    stdio: 'ignore',
    detached: true,
  });
  child.unref();
  const state = loadState();
  state[containerId] = { pid: child.pid, exitCode: null, labels };
  saveState(state);
  process.stdout.write(containerId + '\\n');
  process.exit(0);
}

if (cmd === 'wait') {
  const cid = args[1];
  const maxWait = 30_000;
  const start = Date.now();
  const poll = () => {
    const state = loadState();
    if (!state[cid]) { process.stdout.write('0\\n'); process.exit(0); }
    const { pid } = state[cid];
    let running = true;
    try { process.kill(pid, 0); } catch { running = false; }
    if (!running) { process.stdout.write(String(state[cid].exitCode ?? 0) + '\\n'); process.exit(0); }
    if (Date.now() - start > maxWait) { process.stdout.write('1\\n'); process.exit(0); }
    setTimeout(poll, 100);
  };
  setTimeout(poll, 50);
  return;
}

if (cmd === 'rm') {
  const cid = args[1];
  const state = loadState();
  delete state[cid];
  saveState(state);
  process.exit(0);
}

if (cmd === 'stop') {
  const cid = args[1];
  const state = loadState();
  if (state[cid]) { try { process.kill(state[cid].pid, 'SIGTERM'); } catch {} }
  process.exit(0);
}

if (cmd === 'ps') {
  const state = loadState();
  const lines = [];
  for (const [cid, entry] of Object.entries(state)) {
    const { pid, labels, exitCode } = entry;
    let running = true;
    try { process.kill(pid, 0); } catch { running = false; }
    const status = running ? 'Up 1 second' : \`Exited (\${exitCode ?? 0}) 1 second ago\`;
    const handle = (labels || {})['platform.handle'] || '';
    if (handle) lines.push(cid + '\\t' + handle + '\\t' + status);
  }
  process.stdout.write(lines.join('\\n') + (lines.length ? '\\n' : ''));
  process.exit(0);
}

process.stderr.write('fake-docker: unknown: ' + args.join(' ') + '\\n');
process.exit(1);
`;
  writeFileSync(dockerBin, script, { mode: 0o755 });
  return dockerBin;
}

/** Write a runner script that POSTs a successful completion to the broker. */
function writeSuccessRunner(dir: string, name: string): string {
  const runnerPath = join(dir, name);
  writeFileSync(
    runnerPath,
    [
      `const http = require("node:http");`,
      `const { CALLBACK_URL, HANDLE, NONCE } = process.env;`,
      `const body = JSON.stringify({ handle: HANDLE, nonce: NONCE, result: { terminal_status: "in_review", pr_url: "https://github.com/org/repo/pull/99" } });`,
      `const url = new URL(CALLBACK_URL);`,
      `const req = http.request({ hostname: url.hostname, port: Number(url.port), path: url.pathname, method: "POST", headers: { "Content-Type": "application/json", "Content-Length": Buffer.byteLength(body) } }, (res) => { res.resume(); process.exit(0); });`,
      `req.on("error", (e) => { process.stderr.write(e.message + "\\n"); process.exit(1); });`,
      `req.write(body); req.end();`,
    ].join("\n"),
  );
  return runnerPath;
}

/** Drain up to `count` completions from broker, returning acked handles. */
async function drainN(
  broker: InMemoryBrokerAdapter,
  count: number,
  timeoutMs = 30_000,
): Promise<string[]> {
  const drained: string[] = [];
  const deadline = Date.now() + timeoutMs;
  while (drained.length < count && Date.now() < deadline) {
    const items = await broker.listCompleted({ max: count, lockMs: 30_000 });
    for (const item of items) {
      await broker.ack(item.handle);
      drained.push(item.handle);
      if (drained.length >= count) break;
    }
    if (drained.length < count) {
      await new Promise((r) => setTimeout(r, 50));
    }
  }
  return drained;
}

// ── Suite setup ───────────────────────────────────────────────────────────────

let broker: InMemoryBrokerAdapter;
let callbackUrl: string;

beforeEach(async () => {
  broker = new InMemoryBrokerAdapter({ reclaimIntervalMs: 60_000 });
  await broker.start();
  callbackUrl = broker.getCallbackUrl()!;
});

afterEach(async () => {
  await broker.stop();
  while (tmpDirs.length) {
    const d = tmpDirs.pop()!;
    try { rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
  }
});

// ── Tests ─────────────────────────────────────────────────────────────────────

describe("M:N topology — 3 orchestrators, 5 tasks, shared broker", () => {
  it("all 5 completions are drained; at least one is cross-adapter (opportunistic dispatch)", async () => {
    const dir = makeTmpDir("mn-topology-");
    const stateFile = join(dir, "state.json");
    const dockerBin = writeFakeDocker(dir, stateFile);
    const runnerPath = writeSuccessRunner(dir, "runner.cjs");

    // 3 DockerRunAdapter instances — all wired to the SAME shared broker.
    const adapterA = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });
    const adapterB = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });
    const adapterC = new DockerRunAdapter({
      broker,
      dockerBin,
      runnerEntrypoint: runnerPath,
      crashGraceMs: 500,
      timeoutMs: 20_000,
      orphanSweepIntervalMs: 0,
    });

    // Submit 5 tasks: A=2, B=2, C=1.
    const tasks = [
      { adapter: adapterA, taskId: "T-mn-A1" },
      { adapter: adapterA, taskId: "T-mn-A2" },
      { adapter: adapterB, taskId: "T-mn-B1" },
      { adapter: adapterB, taskId: "T-mn-B2" },
      { adapter: adapterC, taskId: "T-mn-C1" },
    ] as const;

    const submitted: { handle: string; submittedBy: "A" | "B" | "C"; taskId: string }[] = [];

    for (const { adapter, taskId } of tasks) {
      const resultPath = join(dir, `result-${taskId}.json`);
      const nonce = randomUUID();
      const handle = await adapter.submit(
        makeInput({ resultPath, callbackUrl, nonce, taskId }),
      );
      const submittedBy = adapter === adapterA ? "A" : adapter === adapterB ? "B" : "C";
      submitted.push({ handle, submittedBy, taskId });
    }

    // All 5 handles are tracked in the shared broker.
    expect(broker.registrySize()).toBe(5);

    // Drain all 5 completions from ONE drainer (simulates any orchestrator polling).
    // This demonstrates opportunistic dispatch: adapterA's drainer can drain
    // completions submitted by adapterB and adapterC.
    const allHandles = await drainN(broker, 5, 30_000);

    expect(allHandles).toHaveLength(5);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);

    // Verify every submitted handle was drained exactly once.
    const drainedSet = new Set(allHandles);
    for (const { handle } of submitted) {
      expect(drainedSet.has(handle)).toBe(true);
    }

    adapterA.stopOrphanSweep();
    adapterB.stopOrphanSweep();
    adapterC.stopOrphanSweep();
  }, 30_000);
});

describe("M:N topology — concurrent drain race (multiple poller race)", () => {
  it("3 concurrent drainers collectively drain all 5 tasks exactly once", async () => {
    const dir = makeTmpDir("mn-race-");
    const stateFile = join(dir, "state.json");
    const dockerBin = writeFakeDocker(dir, stateFile);
    const runnerPath = writeSuccessRunner(dir, "runner.cjs");

    // All 3 adapters share the same broker.
    const adapters = [0, 1, 2].map(
      () =>
        new DockerRunAdapter({
          broker,
          dockerBin,
          runnerEntrypoint: runnerPath,
          crashGraceMs: 500,
          timeoutMs: 20_000,
          orphanSweepIntervalMs: 0,
        }),
    );

    // Submit 5 tasks round-robin across the 3 adapters.
    const handles: string[] = [];
    for (let i = 0; i < 5; i++) {
      const taskId = `T-race-${i}`;
      const resultPath = join(dir, `result-${taskId}.json`);
      const nonce = randomUUID();
      const handle = await adapters[i % 3].submit(
        makeInput({ resultPath, callbackUrl, nonce, taskId }),
      );
      handles.push(handle);
    }

    expect(handles).toHaveLength(5);

    // 3 concurrent drainers race to drain completions — simulates 3 orchestrators
    // each running their reap-loop concurrently.
    const allDrained: string[] = [];
    const lock = { active: false };

    async function drainer(): Promise<void> {
      const deadline = Date.now() + 30_000;
      while (allDrained.length < 5 && Date.now() < deadline) {
        const items = await broker.listCompleted({ max: 3, lockMs: 10_000 });
        for (const item of items) {
          await broker.ack(item.handle);
          allDrained.push(item.handle);
        }
        if (items.length === 0) {
          await new Promise((r) => setTimeout(r, 50));
        }
      }
    }

    // Race 3 drainers in parallel — peek-and-lock ensures no double-drain.
    await Promise.all([drainer(), drainer(), drainer()]);

    // All 5 completions drained exactly once (no duplicates because peek-and-lock
    // makes each completion visible to only one drainer at a time).
    expect(allDrained).toHaveLength(5);
    expect(new Set(allDrained).size).toBe(5);
    expect(broker.queueDepth()).toBe(0);
    expect(broker.registrySize()).toBe(0);

    for (const adapter of adapters) adapter.stopOrphanSweep();
  }, 30_000);
});

