/**
 * HttpBrokerAdapter — CompletionBrokerPort adapter for the local-docker profile.
 *
 * Routes all broker operations to the shared Go broker service (T7) via HTTP.
 * The callback URL is the broker's POST /callback endpoint, passed to runners
 * via CALLBACK_URL env so they can POST completions directly without knowing
 * which orchestrator submitted.
 *
 * Routes used:
 *   POST /register        → broker.register()
 *   POST /list-completed  → broker.listCompleted()
 *   POST /ack             → broker.ack()
 *   POST /nack            → broker.nack()
 */

import * as http from "node:http";
import * as https from "node:https";
import type {
  CompletionBrokerPort,
  ExecutorHandle,
  HandleMetadata,
  ExecutorCompletion,
} from "@workflow/runtime-abi";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface HttpBrokerAdapterOpts {
  /**
   * Base URL of the Go broker service (no trailing slash).
   * e.g. "http://broker:7000"
   */
  brokerUrl: string;

  /**
   * Override the callback URL returned by getCallbackUrl().
   * Defaults to `<brokerUrl>/callback`.
   */
  callbackUrl?: string;

  /**
   * Request timeout in milliseconds. Default: 10 000.
   */
  timeoutMs?: number;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function post(url: string, body: unknown, timeoutMs: number): Promise<{ status: number; body: string }> {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify(body);
    let u: URL;
    try {
      u = new URL(url);
    } catch {
      reject(new Error(`HttpBrokerAdapter: invalid URL: ${url}`));
      return;
    }
    const lib: typeof http | typeof https = u.protocol === "https:" ? https : http;
    const req = lib.request(
      {
        hostname: u.hostname,
        port: u.port || (u.protocol === "https:" ? 443 : 80),
        path: u.pathname + u.search,
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Content-Length": Buffer.byteLength(payload),
        },
        timeout: timeoutMs,
      },
      (res) => {
        const chunks: Buffer[] = [];
        res.on("data", (c: Buffer) => chunks.push(c));
        res.on("end", () => {
          resolve({
            status: res.statusCode ?? 0,
            body: Buffer.concat(chunks).toString("utf-8"),
          });
        });
      },
    );
    req.on("timeout", () => {
      req.destroy();
      reject(new Error(`HttpBrokerAdapter: request to ${url} timed out after ${timeoutMs}ms`));
    });
    req.on("error", reject);
    req.write(payload);
    req.end();
  });
}

// ── HttpBrokerAdapter ─────────────────────────────────────────────────────────

export class HttpBrokerAdapter implements CompletionBrokerPort {
  private readonly brokerUrl: string;
  private readonly _callbackUrl: string;
  private readonly timeoutMs: number;

  constructor(opts: HttpBrokerAdapterOpts) {
    this.brokerUrl = opts.brokerUrl.replace(/\/$/, "");
    this._callbackUrl = opts.callbackUrl ?? `${this.brokerUrl}/callback`;
    this.timeoutMs = opts.timeoutMs ?? 10_000;
  }

  /**
   * The URL runners should POST { handle, nonce, result } to.
   * Passed via CALLBACK_URL env var at executor spawn time.
   */
  getCallbackUrl(): string {
    return this._callbackUrl;
  }

  async register(
    handle: ExecutorHandle,
    nonce: string,
    metadata: HandleMetadata,
  ): Promise<void> {
    const { status, body } = await post(
      `${this.brokerUrl}/register`,
      { handle, nonce, metadata },
      this.timeoutMs,
    );
    if (status !== 204 && status !== 409) {
      throw new Error(`HttpBrokerAdapter register: unexpected status ${status}: ${body}`);
    }
    // 409 = already registered (idempotent — skip)
  }

  async listCompleted(opts?: { max?: number; lockMs?: number }): Promise<ExecutorCompletion[]> {
    const { status, body } = await post(
      `${this.brokerUrl}/list-completed`,
      {
        max: opts?.max ?? 10,
        lock_ms: opts?.lockMs ?? 30_000,
      },
      this.timeoutMs,
    );
    if (status !== 200) {
      throw new Error(`HttpBrokerAdapter listCompleted: unexpected status ${status}: ${body}`);
    }
    const items = JSON.parse(body) as Array<{
      handle: string;
      result: ExecutorCompletion["result"];
      metadata: HandleMetadata;
      locked_until?: number;
    }>;
    return items.map((item) => ({
      handle: item.handle,
      result: item.result,
      metadata: item.metadata,
      locked_until: item.locked_until,
    }));
  }

  async ack(handle: ExecutorHandle): Promise<void> {
    const { status, body } = await post(
      `${this.brokerUrl}/ack`,
      { handle },
      this.timeoutMs,
    );
    if (status !== 204) {
      throw new Error(`HttpBrokerAdapter ack: unexpected status ${status}: ${body}`);
    }
  }

  async nack(handle: ExecutorHandle): Promise<void> {
    const { status, body } = await post(
      `${this.brokerUrl}/nack`,
      { handle },
      this.timeoutMs,
    );
    if (status !== 204) {
      throw new Error(`HttpBrokerAdapter nack: unexpected status ${status}: ${body}`);
    }
  }
}

